```sql
/* Возраст самого влиятельного пользователя (с максимальной репутацией) */
SELECT "u"."age"
FROM "users" AS "u"
WHERE "u"."reputation" = (
    SELECT MAX("reputation") FROM "users"
)
ORDER BY "u"."age" DESC NULLS LAST
LIMIT 1;
```

```sql
/* Находим минимальную репутацию среди пользователей */
WITH min_rep AS (
    SELECT MIN("reputation") AS min_reputation
    FROM "users"
)
/* Выбираем названия бейджей, полученных пользователями с минимальной репутацией */
SELECT DISTINCT b."name"
FROM "badges" b
JOIN "users" u ON u."id" = b."userid"
JOIN min_rep m ON u."reputation" = m.min_reputation
ORDER BY b."name" ASC NULLS FIRST;
```

```sql
/* Подсчёт общего количества комментариев, оставленных пользователем с userid = 13 */
