```

```sql
/* Подсчёт пользователей, получивших более 5 бейджей */
SELECT COUNT(*) AS user_count
FROM (
    SELECT b."userid"
    FROM "badges" b
    GROUP BY b."userid"
    HAVING COUNT(b."name") > 5
) AS t;
```

